    Bug 2024170 - Ignore system address books for first run check. r=tobyp

    Differential Revision: https://phabricator.services.mozilla.com/D288421

diff --git a/mail/components/accountcreation/modules/FirstRun.sys.mjs b/mail/components/accountcreation/modules/FirstRun.sys.mjs
index 90d0721175e..2a0098f2986 100644
--- a/mail/components/accountcreation/modules/FirstRun.sys.mjs
+++ b/mail/components/accountcreation/modules/FirstRun.sys.mjs
@@ -28,10 +28,15 @@ export function isFirstRun() {
   if (calendarDeactivator.checkCalendarsEnabled()) {
     return false;
   }
-  // If there is an address book with a contact, the profile is set up.
+  // If there is an address book with a contact, the profile is set up. We
+  // ignore the OS X system address books and address books from outlook for
+  // this check, since they are system data sources.
   if (
     MailServices.ab.directories.some(
-      abDirectory => abDirectory.childCardCount > 0
+      abDirectory =>
+        !abDirectory.URI.startsWith("moz-abosxdirectory:") &&
+        !abDirectory.URI.startsWith("moz-aboutlookdirectory:") &&
+        abDirectory.childCardCount > 0
     )
   ) {
     return false;
diff --git a/mail/components/accountcreation/test/xpcshell/test_firstRun.js b/mail/components/accountcreation/test/xpcshell/test_firstRun.js
index 4721c73eb54..1af22a91a10 100644
--- a/mail/components/accountcreation/test/xpcshell/test_firstRun.js
+++ b/mail/components/accountcreation/test/xpcshell/test_firstRun.js
@@ -161,3 +161,28 @@ add_task(function testFirstRunWithInvalidMailAccount() {

   MailServices.accounts.removeAccount(account, true);
 });
+
+add_task(
+  { skip_if: () => AppConstants.platform != "macos" },
+  function testFirstRunIgnoresMacOSAddressBook() {
+    let hadAddressBook = false;
+    try {
+      MailServices.ab.newAddressBook(
+        "test",
+        "moz-abosxdirectory:///",
+        Ci.nsIAbManager.MAPI_DIRECTORY_TYPE
+      );
+    } catch {
+      hadAddressBook = true;
+    }
+
+    Assert.ok(
+      isFirstRun(),
+      "Should indicate first run even with native address book"
+    );
+
+    if (!hadAddressBook) {
+      MailServices.ab.deleteAddressBook("moz-abosxdirectory:///");
+    }
+  }
+);
